INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6401251, 948666, 108580, '<td valign="top">Vibrant, colourful, dramatic and in your face. Perhaps a bit too much so.<br/>Great composition and sky. I''d tone it down just a bit and ease off on the HDR sliders :) Still a wonderful shot that took a lot of effort to take and make.</td>', 'Vibrant, colourful, dramatic and in your face. Perhaps a bit too much so.Great composition and sky. I''d tone it down just a bit and ease off on the HDR sliders :) Still a wonderful shot that took a lot of effort to take and make.', '2011-05-02 05:15:24.000000', NULL, 1),
(6401253, 948798, 108580, '<td valign="top">Most unusual entry for a FS. Interesting light and positioning of groups. Pillars add stability to an otherwise motive image. Hope you''re not getting caned.</td>', 'Most unusual entry for a FS. Interesting light and positioning of groups. Pillars add stability to an otherwise motive image. Hope you''re not getting caned.', '2011-05-02 05:28:11.000000', NULL, 1),
(6401258, 948387, 108580, '<td valign="top">Lovely work. Add some film grain and it could be the 50''s. <br/>Your sensor needs a clean and you could have removed the dust bunnies (Above Lamp 1 and Lamp 3 from left) in Advanced Editing. Seems a pity.</td>', 'Lovely work. Add some film grain and it could be the 50''s. Your sensor needs a clean and you could have removed the dust bunnies (Above Lamp 1 and Lamp 3 from left) in Advanced Editing. Seems a pity.', '2011-05-02 05:36:47.000000', NULL, 1),
(6401260, 948934, 108580, '<td valign="top">Beautiful image. The cloud blanket between fore and aft is very serene especially after a rain storm. I''d like to see more of the foreground. <br/>I think you processed very little here and maybe in a FS a little (more?) sharpening and saturation will get you slightly higher vote average.<br/>Hope you have a few more with various horison level changes, i.e. a bit more foreground, less sky.</td>', 'Beautiful image. The cloud blanket between fore and aft is very serene especially after a rain storm. I''d like to see more of the foreground. I think you processed very little here and maybe in a FS a little (more?) sharpening and saturation will get you slightly higher vote average.Hope you have a few more with various horison level changes, i.e. a bit more foreground, less sky.', '2011-05-02 05:46:04.000000', NULL, 1),
(6401267, 948774, 108580, '<td valign="top">This location is always a winner. Getting a unique POV now must be quite a challenge? Lovely flowing geology and colours.</td>', 'This location is always a winner. Getting a unique POV now must be quite a challenge? Lovely flowing geology and colours.', '2011-05-02 06:24:50.000000', NULL, 1),
(6401268, 944926, 108580, '<td valign="top">I can''t imagine what it took to get this image. I feel a bit more effort in PP would have done it more justice. The vignetting in the corners is your filter ring. Can be removed in PP in a FS.</td>', 'I can''t imagine what it took to get this image. I feel a bit more effort in PP would have done it more justice. The vignetting in the corners is your filter ring. Can be removed in PP in a FS.', '2011-05-02 06:28:02.000000', NULL, 1),
