(6404729, 945334, 119419, '<td valign="top">Beautiful mono, wonderful lighting, maybe a tad too much on the dog''s hind and right side of face. The human model lighting I like, makes for the mood. Well done.8</td>', 'Beautiful mono, wonderful lighting, maybe a tad too much on the dog''s hind and right side of face. The human model lighting I like, makes for the mood. Well done.8', '2011-05-05 01:49:12.000000', NULL, 1),
(6404730, 948867, 119419, '<td valign="top">Good shot, clear, nice tones, balance and symmetry only I''m wanting the bird to be more squared in the picture which means I''m ruining it for you ;) 7</td>', 'Good shot, clear, nice tones, balance and symmetry only I''m wanting the bird to be more squared in the picture which means I''m ruining it for you ;) 7', '2011-05-05 01:52:51.000000', NULL, 1),
