(6404733, 947671, 119419, '<td valign="top">Compelling and evil. Detail a little flat on the snout but a good effort.</td>', 'Compelling and evil. Detail a little flat on the snout but a good effort.', '2011-05-05 01:56:22.000000', NULL, 1),
(6404736, 947782, 119419, '<td valign="top">Great shot for tone and content. Great positioning of hands. Something strange about the left boot and the shadow in front of it that distracts me. I would have toned the bright light up the top but I put my thumb over it and it went away ;) I like this one, it has character 7</td>', 'Great shot for tone and content. Great positioning of hands. Something strange about the left boot and the shadow in front of it that distracts me. I would have toned the bright light up the top but I put my thumb over it and it went away ;) I like this one, it has character 7', '2011-05-05 01:59:46.000000', NULL, 1),
(6404738, 948983, 119419, '<td valign="top">Good street shot, probably would like to see it with less of the pink in the left background though, kind of pulls my eye away from the main subjects 7</td>', 'Good street shot, probably would like to see it with less of the pink in the left background though, kind of pulls my eye away from the main subjects 7', '2011-05-05 02:02:10.000000', NULL, 1),
(6404740, 948798, 119419, '<td valign="top">Brilliant example of this style 7</td>', 'Brilliant example of this style 7', '2011-05-05 02:03:22.000000', NULL, 1),
(6404750, 949008, 119419, '<td valign="top">Ok your top doesn''t fit and you''re hiding the remote in your right hand ;) Nice even lighting on skin, leading edge of divan is a little blown out - looks like sunlight, but does pull your attention to the face. Great expression, cheeky and playful. It does have a good balance to the composition but the middle cushion needs attention. Fun shot.</td>', 'Ok your top doesn''t fit and you''re hiding the remote in your right hand ;) Nice even lighting on skin, leading edge of divan is a little blown out - looks like sunlight, but does pull your attention to the face. Great expression, cheeky and playful. It does have a good balance to the composition but the middle cushion needs attention. Fun shot.', '2011-05-05 02:14:51.000000', NULL, 1),
(6404752, 948157, 119419, '<td valign="top">Very nice</td>', 'Very nice', '2011-05-05 02:15:29.000000', NULL, 1),
