(6405004, 949050, 67152, '<td valign="top">lovely composition - i just wonder about the light - the bottom of the image including the boats and water in front does not quite match the foreboding darkness of the sky above</td>', 'lovely composition - i just wonder about the light - the bottom of the image including the boats and water in front does not quite match the foreboding darkness of the sky above', '2011-05-05 13:24:23.000000', NULL, 1),
(6405016, 949064, 67152, '<td valign="top">lovely macro - the richness and softness of the petals is emphasized by the shallow DOF and this is so expertly contrasted with the sharpness of the edges of the leaves and the center of the flower</td>', 'lovely macro - the richness and softness of the petals is emphasized by the shallow DOF and this is so expertly contrasted with the sharpness of the edges of the leaves and the center of the flower', '2011-05-05 13:50:13.000000', NULL, 1),
