(6406664, 948529, 76335, '<td valign="top">What a life! Lots of great details to savor here (those chairs!). And the vessel itself is a throwback to an earlier time.</td>', 'What a life! Lots of great details to savor here (those chairs!). And the vessel itself is a throwback to an earlier time.', '2011-05-07 16:51:18.000000', NULL, 1),
(6406666, 945309, 76335, '<td valign="top">Horizons are distracting anyway. Who needs them? This is perfect.</td>', 'Horizons are distracting anyway. Who needs them? This is perfect.', '2011-05-07 16:51:27.000000', NULL, 1),
(6406667, 948905, 76335, '<td valign="top">Once again, nicely done. Your compositional style is worthy of study. Nothing dominates the frame in the classical I-am-the-focal-point sense. Rather, the interest seems to come from unexpected places -- margins, corners, backgrounds, etc. To borrow a hackneyed expression, the end result is greater than the sum of the parts.</td>', 'Once again, nicely done. Your compositional style is worthy of study. Nothing dominates the frame in the classical I-am-the-focal-point sense. Rather, the interest seems to come from unexpected places -- margins, corners, backgrounds, etc. To borrow a hackneyed expression, the end result is greater than the sum of the parts.', '2011-05-07 16:51:32.000000', NULL, 1),
(6406668, 948625, 76335, '<td valign="top">I like the quirky composition, though I suspect you''ll get some comments about cropping too much/not enough here or there. <br/> <br/>Perfect.</td>', 'I like the quirky composition, though I suspect you''ll get some comments about cropping too much/not enough here or there.  Perfect.', '2011-05-07 16:51:36.000000', NULL, 1),
(6406669, 947955, 76335, '<td valign="top">Astounding. It''s all about the lines -- the posts sit haphazardly and the barbed wire leads us drunkenly toward the horizon. And that twist of cloud -- perfect.</td>', 'Astounding. It''s all about the lines -- the posts sit haphazardly and the barbed wire leads us drunkenly toward the horizon. And that twist of cloud -- perfect.', '2011-05-07 16:51:43.000000', NULL, 1),
(6406670, 948564, 76335, '<td valign="top">A geometer''s delight. Great framing.</td>', 'A geometer''s delight. Great framing.', '2011-05-07 16:51:54.000000', NULL, 1),
