INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6407624, 949114, 20799, '<td valign="top">Wow, Joe, I love this! The blaze, the flying things, the big black "eyes" in the background and most of all the position of the two figures, such a great story! Great image.<br/>Btw... <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=97225" rel="nofollow" target="_blank">jomari</a> mentions carbon deposit... didn''t you have your camera repaired, and was it after this event??<br/></td>', 'Wow, Joe, I love this! The blaze, the flying things, the big black "eyes" in the background and most of all the position of the two figures, such a great story! Great image.Btw...  jomari mentions carbon deposit... didn''t you have your camera repaired, and was it after this event??', '2011-05-08 14:27:18.000000', NULL, 0),
(6407625, 949050, 62357, '<td valign="top">Lovely!  It did pretty well too.  Hope we are going to see some more of your work soon!</td>', 'Lovely!  It did pretty well too.  Hope we are going to see some more of your work soon!', '2011-05-08 14:28:41.000000', NULL, 0),
