(6407652, 945334, 108580, '<td valign="top">Very well done Jo! Enjoy the long fought ribbon!</td>', 'Very well done Jo! Enjoy the long fought ribbon!', '2011-05-08 15:28:09.000000', NULL, 0),
(6407659, 946670, 52686, '<td valign="top">Thank you for the comments.  :-)  This was taken at sunset.  The egret was landing on the water, into the sun that was hovering just above the mangroves a short distance away, leaving them in dark shadow.  With the egrets wings backlit and the water glistening in places, the exposure was already very low on the mangroves and the majority of the water surface.  A bit of adjustment on Curves and a bit of Burn allowed the background to drop away completely.  All in all, it was a pure luck shot. Right time, right place.  ...was hoping it might have done slightly better than 5.9, but it''s not a great quality image, so I guess it''s pretty fair.</td>', 'Thank you for the comments.  :-)  This was taken at sunset.  The egret was landing on the water, into the sun that was hovering just above the mangroves a short distance away, leaving them in dark shadow.  With the egrets wings backlit and the water glistening in places, the exposure was already very low on the mangroves and the majority of the water surface.  A bit of adjustment on Curves and a bit of Burn allowed the background to drop away completely.  All in all, it was a pure luck shot. Right time, right place.  ...was hoping it might have done slightly better than 5.9, but it''s not a great quality image, so I guess it''s pretty fair.', '2011-05-08 15:44:09.000000', NULL, 0),
(6407666, 948798, 50695, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tnun:</b></div><hr/><i> Like the old masters - socrates and the other greats hanging about the stoa. </i></td></tr></table> <br/> <br/>Yes, add some Raphael to my Bacon!</td>', 'Originally posted by tnun: Like the old masters - socrates and the other greats hanging about the stoa.   Yes, add some Raphael to my Bacon!', '2011-05-08 15:48:53.000000', NULL, 0),
(6407670, 949144, 50695, '<td valign="top">this is one of those rare times a posthumous ribbon actually brings down the commenter''s average. oops!</td>', 'this is one of those rare times a posthumous ribbon actually brings down the commenter''s average. oops!', '2011-05-08 15:50:47.000000', NULL, 0),
(6407672, 949027, 20799, '<td valign="top">Oh this needs more pixels! Fantastic scene and processing. I should have recognized this place :). The Plitvice national park needs to find out about this image... I''m sure they would contact you.</td>', 'Oh this needs more pixels! Fantastic scene and processing. I should have recognized this place :). The Plitvice national park needs to find out about this image... I''m sure they would contact you.', '2011-05-08 15:53:08.000000', NULL, 0),
